<script lang="ts">
  import { onDestroy,onMount } from 'svelte';
import { summarizeTouchscreenSession, validateUtilityParams, type TouchscreenRect, type TouchscreenReport, type ToolModule } from '@wyreup/core/execution';
  import type { SerializedTool } from './types';
  import { createTouchscreenCollector } from './touchscreen-session';
  export let tool:SerializedTool;
  export let injectedTool:ToolModule<Record<string,unknown>>|undefined=undefined;
  let columnsDraft=String(tool.defaults.columns),rowsDraft=String(tool.defaults.rows),columns=Number(tool.defaults.columns),rows=Number(tool.defaults.rows),canvas:HTMLCanvasElement;
  let session:ReturnType<typeof createTouchscreenCollector>|null=null,active=false,report:TouchscreenReport|null=null,error='',status='Not measured. Start, sweep the canvas, then Stop.',accepted=0,excluded=0;
  const cache=new Map<string,unknown>(),captures=new Set<number>();let generation=0,controller:AbortController|null=null,url:string|null=null,exporting=false;
  function invalidateExport(){generation++;controller?.abort();controller=null;exporting=false;if(url)URL.revokeObjectURL(url);url=null;}
  function rect():TouchscreenRect{const value=canvas.getBoundingClientRect();return{left:value.left,top:value.top,width:value.width,height:value.height};}
  function release(){for(const id of captures)try{if(canvas?.hasPointerCapture(id))canvas.releasePointerCapture(id);}catch{}captures.clear();}
  function paint(){if(!canvas)return;const r=rect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));const ctx=canvas.getContext('2d');if(!ctx){error='Canvas drawing is unavailable.';return;}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#f3f5f3';ctx.fillRect(0,0,r.width,r.height);const cells=session?.cells??[];for(let row=0;row<rows;row++)for(let column=0;column<columns;column++){const x=column*r.width/columns,y=row*r.height/rows;if(cells[row*columns+column]){ctx.fillStyle='#95c5a6';ctx.fillRect(x,y,r.width/columns,r.height/rows);}ctx.strokeStyle='#59695d';ctx.strokeRect(x,y,r.width/columns,r.height/rows);}}
  function reset(){invalidateExport();session?.dispose();session=null;active=false;release();cache.delete('wyreup:touchscreen-session');report=null;accepted=0;excluded=0;status='Not measured. Start a new session.';paint();}
  function gridChanged(key:'columns'|'rows',event:Event){reset();const raw=(event.currentTarget as HTMLInputElement).value;if(key==='columns')columnsDraft=raw;else rowsDraft=raw;error='';try{const p=validateUtilityParams(tool.defaults,tool.paramSchema!,{columns:columnsDraft.trim()?Number(columnsDraft):null,rows:rowsDraft.trim()?Number(rowsDraft):null});columns=p.columns as number;rows=p.rows as number;paint();}catch(cause){error=cause instanceof Error?cause.message:'Invalid grid.';}}
  function start(){reset();error='';try{const p=validateUtilityParams(tool.defaults,tool.paramSchema!,{columns:columnsDraft.trim()?Number(columnsDraft):null,rows:rowsDraft.trim()?Number(rowsDraft):null});columns=p.columns as number;rows=p.rows as number;session=createTouchscreenCollector({columns,rows,rect:rect(),now:()=>performance.now(),setTimer:(callback,ms)=>window.setTimeout(callback,ms),clearTimer:id=>window.clearTimeout(id),stopped:(reason,snapshot)=>{active=false;release();cache.set('wyreup:touchscreen-session',snapshot);const counts=session?.counts();accepted=counts?.accepted??snapshot.samples.length;excluded=counts?.excluded??snapshot.excludedSamples;status=reason;try{report=summarizeTouchscreenSession(snapshot,{columns,rows});}catch(cause){report=null;error=cause instanceof Error?cause.message:'Not measured.';}}});active=true;status='Measuring local pointer samples. Mouse and pen are labelled separately.';paint();}catch(cause){error=cause instanceof Error?cause.message:'Cannot start measurement.';}}
  function stop(){invalidateExport();session?.stop();}
  function pointer(event:PointerEvent){if(!active||!session)return;if(!session.matches(rect())){reset();error='Canvas geometry changed; start a new measurement.';return;}try{session.record(event);const counts=session.counts();accepted=counts.accepted;excluded=counts.excluded;if(event.type==='pointerdown'){try{canvas.setPointerCapture(event.pointerId);captures.add(event.pointerId);}catch{}}if(event.type==='pointerup'){try{if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);}catch{}captures.delete(event.pointerId);}paint();}catch(cause){reset();error=cause instanceof Error?cause.message:'Pointer measurement failed.';}}
  function pointerCancel(event:PointerEvent){try{if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);}catch{}captures.delete(event.pointerId);}
  function geometry(){if(session?.isActive()&&!session.matches(rect())){reset();error='Canvas geometry changed; start a new measurement.';}}
  function resize(){if(session?.isActive()){reset();status='Grid reset after resize/orientation change. Start a new measurement.';}else paint();}
  async function download(){if(!report||active||error)return;invalidateExport();const own=generation,control=new AbortController();controller=control;exporting=true;try{const module=injectedTool??(await import('../../lib/core-execution')).createDefaultRegistry().toolsById.get(tool.id);if(own!==generation)return;if(!module)throw new Error('Tool unavailable.');const result=await module.run([],{columns,rows},{signal:control.signal,executionId:crypto.randomUUID(),cache,onProgress(){}});if(own!==generation)return;const blobs=Array.isArray(result)?result:[result];if(blobs.length!==1||blobs[0]!.type!=='application/json')throw new Error('Expected one JSON report.');url=URL.createObjectURL(blobs[0]!);const a=document.createElement('a');a.href=url;a.download='touchscreen-report.json';a.click();}catch(cause){if(own===generation)error=cause instanceof Error?cause.message:'Export failed.';}finally{if(own===generation){exporting=false;controller=null;}}}
  onMount(()=>{paint();window.addEventListener('resize',resize);window.addEventListener('orientationchange',resize);window.addEventListener('scroll',geometry,true);});
  onDestroy(()=>{invalidateExport();session?.dispose();cache.clear();release();window.removeEventListener('resize',resize);window.removeEventListener('orientationchange',resize);window.removeEventListener('scroll',geometry,true);});
</script>
<div class="touchscreen">
  <p>Start a bounded local measurement and sweep the canvas. No camera or device permission request. Grid coordinates use CSS pixels; the display scales for device pixel ratio.</p>
  <div class="grid-controls"><label>Columns<input aria-label="Columns" type="number" min="2" max="50" step="1" value={columnsDraft} on:input={event=>gridChanged('columns',event)}/></label><label>Rows<input aria-label="Rows" type="number" min="2" max="50" step="1" value={rowsDraft} on:input={event=>gridChanged('rows',event)}/></label></div>
  <div class="actions"><button type="button" disabled={active||!!error} on:click={start}>Start</button><button type="button" disabled={!active} on:click={stop}>Stop</button><button type="button" on:click={()=>{reset();error='';}}>Reset</button><button type="button" disabled={!report||active||!!error||exporting} on:click={download}>Export JSON</button></div>
  <canvas bind:this={canvas} aria-label="Pointer measurement canvas" on:pointerdown={pointer} on:pointermove={pointer} on:pointerup={pointer} on:pointercancel={pointerCancel}></canvas>
  <p role="status">{status} Accepted samples: {accepted}; excluded samples: {excluded}.</p>{#if error}<p role="alert">{error}</p>{/if}
  {#if report}<section><h3>Measured coverage</h3><p>{report.touchedCells} touched cells; {report.untouchedCells} unvisited cells; {report.coveragePercent}% coverage; {report.durationMs}ms.</p><ul>{#each Object.entries(report.pointerTypeCounts) as [kind,count]}<li>{kind}: {count} observed samples</li>{/each}</ul></section>{/if}
  <p>Coverage and touched cells describe sampled pointer positions. Mouse or pen hover can contribute; pointer types are listed separately. This is not proof of physical contact detection or dead hardware.</p>
  <p>Automatic stop at120 seconds or100000 accepted/excluded samples. During measurement, resize, orientation or canvas position changes reset captured geometry. Stop freezes the captured report; later layout changes preserve it. Grid edits, Reset or a new Start clear a finished report. Pointer-cancel does not invent a final point.</p>
</div>
<style>
  .touchscreen{display:grid;gap:var(--space-3)}.grid-controls{display:flex;gap:var(--space-2);flex-wrap:wrap}label{display:grid;gap:var(--space-1)}canvas{display:block;width:100%;height:300px;box-sizing:border-box;border:1px solid var(--border);touch-action:none}.actions{display:flex;gap:var(--space-2);flex-wrap:wrap}button,input{padding:var(--space-2);font:inherit;background:var(--bg-raised);color:var(--text-primary);border:1px solid var(--border)}button:disabled{opacity:.6}button:focus-visible,input:focus-visible{outline:2px solid var(--accent-text);outline-offset:2px}
</style>
